@@ -0,0 +1,171 @@
+package com.example.views;
+
+import com.example.data.ContactMessage;
+import com.example.data.MessageService;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationVariant;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+import java.time.Instant;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final MessageService messageService;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final EmailValidator emailValidator = new EmailValidator("Enter a valid e-mail address");
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        nameField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(e -> sendButton.setEnabled(true));
+
+        sendButton.addClickListener(e -> trySend());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        refreshGrid();
+
+        add(nameField, emailField, phoneField, messageField, sendButton, grid);
+    }
+
+    private void trySend() {
+        if (!validate()) {
+            return;
+        }
+
+        ContactMessage contactMessage = new ContactMessage(
+                nameField.getValue().trim(),
+                emailField.getValue().trim(),
+                phoneField.getValue().trim(),
+                messageField.getValue().trim(),
+                Instant.now());
+        messageService.add(contactMessage);
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        refreshGrid();
+
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue().trim();
+
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        if (name.isEmpty()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        if (!email.isEmpty() && emailValidator.apply(email, new ValueContext()).isError()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.isEmpty()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            var action = event.postpone();
+
+            Dialog dialog = new Dialog();
+            dialog.setCloseOnEsc(false);
+            dialog.setCloseOnOutsideClick(false);
+            dialog.add(new Span("You have unsaved changes. Leaving now will discard them."));
+
+            Button keepEditing = new Button("Keep editing", e -> dialog.close());
+            Button discard = new Button("Discard", e -> {
+                dialog.close();
+                action.proceed();
+            });
+
+            dialog.getFooter().add(keepEditing, discard);
+            dialog.open();
+        }
+    }
+}
