+package com.example.views;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.dialog.DialogTester;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private ContactView view;
+    private TextField nameField;
+    private EmailField emailField;
+    private TextField phoneField;
+    private TextArea messageField;
+    private Button sendButton;
+    private Grid<?> grid;
+
+    @BeforeEach
+    void setUp() {
+        view = navigate(ContactView.class);
+        nameField = find(TextField.class).withLabel("Name").single();
+        emailField = find(EmailField.class).single();
+        phoneField = find(TextField.class).withLabel("Phone").single();
+        messageField = find(TextArea.class).single();
+        sendButton = find(Button.class).withText("Send").single();
+        grid = find(Grid.class).single();
+    }
+
+    @Test
+    void headingAndAboutLink() {
+        assertEquals("Contact", find(H1.class).single().getText());
+        RouterLink aboutLink = find(RouterLink.class).withText("About").single();
+        assertEquals(true, test(aboutLink).getRoute().isPresent());
+    }
+
+    @Test
+    void formStartsEmptyAndSendEnabled() {
+        assertEquals("", nameField.getValue());
+        assertEquals("", emailField.getValue());
+        assertEquals("", phoneField.getValue());
+        assertEquals("", messageField.getValue());
+        assertTrue(sendButton.isEnabled());
+    }
+
+    @Test
+    void emptyFormFailsValidationAndSendsNothing() {
+        int before = test(GridTester.class, grid).size();
+
+        test(sendButton).click();
+
+        assertTrue(nameField.isInvalid());
+        assertEquals("Name is required", nameField.getErrorMessage());
+        assertTrue(emailField.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", emailField.getErrorMessage());
+        assertTrue(messageField.isInvalid());
+        assertEquals("Message is required", messageField.getErrorMessage());
+
+        assertEquals(before, test(GridTester.class, grid).size());
+        assertTrue(sendButton.isEnabled());
+    }
+
+    @Test
+    void invalidEmailFormatIsRejected() {
+        test(nameField).setValue("Ann");
+        test(emailField).setValue("not-an-email");
+        test(messageField).setValue("Hello there");
+
+        test(sendButton).click();
+
+        assertTrue(emailField.isInvalid());
+        assertEquals("Enter a valid e-mail address", emailField.getErrorMessage());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        test(nameField).setValue("Ann");
+        test(phoneField).setValue("12345");
+        test(messageField).setValue("x".repeat(501));
+
+        test(sendButton).click();
+
+        assertTrue(messageField.isInvalid());
+        assertEquals("Message must be at most 500 characters", messageField.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToSend() {
+        test(nameField).setValue("Ann");
+        test(phoneField).setValue("12345");
+        test(messageField).setValue("Hello there");
+
+        test(sendButton).click();
+
+        assertFalse(nameField.isInvalid());
+        assertFalse(emailField.isInvalid());
+        assertFalse(messageField.isInvalid());
+    }
+
+    @Test
+    void successfulSendClearsFormShowsNotificationAndAddsRow() {
+        int before = test(GridTester.class, grid).size();
+
+        test(nameField).setValue("Ann");
+        test(phoneField).setValue("12345");
+        test(messageField).setValue("Hello there");
+
+        test(sendButton).click();
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(NotificationTester.class, notification).getText().contains("Message sent"));
+
+        assertEquals("", nameField.getValue());
+        assertEquals("", emailField.getValue());
+        assertEquals("", phoneField.getValue());
+        assertEquals("", messageField.getValue());
+
+        assertEquals(before + 1, test(GridTester.class, grid).size());
+        assertFalse(sendButton.isEnabled());
+
+        test(nameField).setValue("x");
+        assertTrue(sendButton.isEnabled());
+    }
+
+    @Test
+    void enterKeySendsForm() {
+        test(nameField).setValue("Ann");
+        test(phoneField).setValue("12345");
+        test(messageField).setValue("Hello there");
+
+        fireShortcut(Key.ENTER);
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(NotificationTester.class, notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void leavingWithUnsavedInputAsksFirst() {
+        test(nameField).setValue("Ann");
+
+        RouterLink aboutLink = find(RouterLink.class).withText("About").single();
+        test(aboutLink).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button keepEditing = find(Button.class, dialog).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertEquals("Ann", nameField.getValue());
+        assertEquals(0, find(Dialog.class).all().size());
+    }
+
+    @Test
+    void discardingNavigatesAway() {
+        test(nameField).setValue("Ann");
+
+        RouterLink aboutLink = find(RouterLink.class).withText("About").single();
+        test(aboutLink).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button discard = find(Button.class, dialog).withText("Discard").single();
+        test(discard).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormNavigatesAwayWithoutAsking() {
+        RouterLink aboutLink = find(RouterLink.class).withText("About").single();
+        test(aboutLink).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+}
